function findRepeat(nums: number[]): number {
  let lo = 1, hi = nums.length - 1;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    let count = 0;
    for (const v of nums) if (v <= mid) count++;
    // more than mid values squeezed into 1..mid means the repeat is there
    if (count > mid) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

